window.SEG=[{"i": 0, "a": 0.25, "b": 2.376, "text": "ثلاث دقات… على باب غرفة الحارس."}, {"i": 1, "a": 2.706, "b": 4.748, "text": "وبعدها سمعنا صوتي أنا من برا:"}, {"i": 2, "a": 5.078, "b": 6.7, "text": "«افتحوا… البرد هنا يذبح.»"}, {"i": 3, "a": 7.03, "b": 8.652, "text": "تقدمت خطوة بدون ما أحس…"}, {"i": 4, "a": 9.232, "b": 11.526, "text": "لكن أبو صالح مسك ذراعي بقوة وقال:"}, {"i": 5, "a": 11.856, "b": 13.142, "text": "«لا تفتح! هذا مو أنت!»"}, {"i": 6, "a": 13.472, "b": 14.758, "text": "وفجأة… جوالي اهتز."}, {"i": 7, "a": 15.088, "b": 16.458, "text": "رسالة من رقم مجهول:"}, {"i": 8, "a": 16.788, "b": 18.914, "text": "«لا تفتحون… اللي برا مو جاي يدخل.»"}, {"i": 9, "a": 19.244, "b": 20.698, "text": "وبعدها رسالة ثانية:"}, {"i": 10, "a": 21.028, "b": 22.398, "text": "«هو يبيكم تطلعون له!»"}, {"i": 11, "a": 22.728, "b": 24.434, "text": "كتبت بيدين ترجف: «مين أنت؟»"}, {"i": 12, "a": 24.764, "b": 26.302, "text": "وجاني الرد بعد ثواني:"}, {"i": 13, "a": 26.632, "b": 29.094, "text": "«اسمي سالم… وإذا تبي تعيش، اسمع كلامي!»"}, {"i": 14, "a": 29.424, "b": 31.718, "text": "رفعت راسي وقلت: «أبو صالح… مين سالم؟»"}, {"i": 15, "a": 32.048, "b": 33.502, "text": "أبو صالح تجمد مكانه…"}, {"i": 16, "a": 34.082, "b": 35.62, "text": "وبعدين قال بصوت واطي:"}, {"i": 17, "a": 35.95, "b": 37.656, "text": "«سالم… اختفى من سبع سنوات."}, {"i": 18, "a": 37.986, "b": 40.28, "text": "كان واحد من سكان العمارة… وما رجع.»"}, {"i": 19, "a": 40.61, "b": 42.316, "text": "تذكرت الصورة الجماعية…"}, {"i": 20, "a": 42.896, "b": 44.602, "text": "الشاب اللي ما كنت أعرفه."}, {"i": 21, "a": 44.932, "b": 46.554, "text": "طالعنا شاشة المراقبة…"}, {"i": 22, "a": 47.134, "b": 49.428, "text": "نواف الثاني كان واقف قدام الباب…"}, {"i": 23, "a": 50.008, "b": 51.63, "text": "وفجأة… اختفى من الصورة."}, {"i": 24, "a": 51.96, "b": 53.078, "text": "الممر صار فاضي."}, {"i": 25, "a": 53.408, "b": 54.778, "text": "لكن الدقات… ما وقفت."}, {"i": 26, "a": 55.108, "b": 55.386, "text": "طق…"}, {"i": 27, "a": 55.966, "b": 56.244, "text": "طق…"}, {"i": 28, "a": 56.824, "b": 57.102, "text": "طق…"}, {"i": 29, "a": 57.682, "b": 60.816, "text": "الكاميرا تقول ما فيه أحد… والباب يقول غير كذا."}, {"i": 30, "a": 61.146, "b": 62.6, "text": "وصلتني رسالة ثالثة:"}, {"i": 31, "a": 62.93, "b": 65.14, "text": "«بعد عشر ثواني… بتنقطع الكهرباء.»"}, {"i": 32, "a": 65.47, "b": 66.504, "text": "طالعت اللمبة…"}, {"i": 33, "a": 67.084, "b": 67.782, "text": "بدت ترمش…"}, {"i": 34, "a": 68.362, "b": 69.396, "text": "وبعدين… انطفت."}, {"i": 35, "a": 69.726, "b": 72.524, "text": "صار الظلام كامل… وما بقى إلا صوت أنفاسنا."}, {"i": 36, "a": 72.854, "b": 74.644, "text": "أبو صالح ولّع كشاف جواله…"}, {"i": 37, "a": 75.224, "b": 76.51, "text": "وراح لرف الأشرطة."}, {"i": 38, "a": 76.84, "b": 77.958, "text": "سحب صندوق قديم…"}, {"i": 39, "a": 78.538, "b": 80.244, "text": "وكان خلفه باب حديد صغير!"}, {"i": 40, "a": 80.574, "b": 83.036, "text": "قال: «هذا درج الطوارئ… ما أحد يعرف عنه.»"}, {"i": 41, "a": 83.366, "b": 85.156, "text": "فتح الباب… وأبوي دخل وراه."}, {"i": 42, "a": 85.486, "b": 87.612, "text": "وأنا تأخرت ثانية… أطالع ورانا."}, {"i": 43, "a": 87.942, "b": 89.312, "text": "وأول ما عديت الباب…"}, {"i": 44, "a": 89.892, "b": 90.758, "text": "تسكّر بقوة!"}, {"i": 45, "a": 91.088, "b": 92.122, "text": "صرت أنا من جهة…"}, {"i": 46, "a": 92.702, "b": 95.08, "text": "وأبوي وأبو صالح من الجهة الثانية!"}, {"i": 47, "a": 95.41, "b": 97.452, "text": "دفيت الباب بكل قوتي… ما انفتح."}, {"i": 48, "a": 97.782, "b": 100.328, "text": "كنت أسمع أبوي يصرخ باسمي… وصوته يبعد."}, {"i": 49, "a": 100.658, "b": 102.196, "text": "كنت لحالي في درج قديم…"}, {"i": 50, "a": 102.776, "b": 104.314, "text": "ينزل لتحت… لين الظلام."}, {"i": 51, "a": 104.644, "b": 106.518, "text": "وفجأة… وصلتني رسالة صوتية."}, {"i": 52, "a": 106.848, "b": 107.462, "text": "من سالم."}, {"i": 53, "a": 107.792, "b": 109.414, "text": "شغلتها… وكان صوته يرجف:"}, {"i": 54, "a": 109.744, "b": 112.374, "text": "«نواف… بعد شوي بتسمع ولد يبكي تحت الدرج."}, {"i": 55, "a": 112.704, "b": 114.074, "text": "لا تروح له… مهما قال.»"}, {"i": 56, "a": 114.404, "b": 115.606, "text": "وانتهت الرسالة."}, {"i": 57, "a": 115.936, "b": 117.054, "text": "وبعدها بثانية…"}, {"i": 58, "a": 117.634, "b": 119.34, "text": "سمعت بكاء ولد… جاي من تحت."}, {"i": 59, "a": 119.67, "b": 120.788, "text": "نزلت درجة وحدة…"}, {"i": 60, "a": 121.368, "b": 121.898, "text": "ووقفت."}, {"i": 61, "a": 122.228, "b": 123.85, "text": "قلت بصوت مخنوق: «مين أنت؟»"}, {"i": 62, "a": 124.18, "b": 125.046, "text": "وقف البكاء."}, {"i": 63, "a": 125.376, "b": 126.662, "text": "وبعد صمت طويل… قال:"}, {"i": 64, "a": 126.992, "b": 128.95, "text": "«أنا سالم… وعمري خمسة عشر سنة."}, {"i": 65, "a": 129.28, "b": 130.734, "text": "وانتظرتك… سبع سنوات.»"}, {"i": 66, "a": 131.064, "b": 132.434, "text": "والحين أبي أسألكم…"}, {"i": 67, "a": 133.014, "b": 133.88, "text": "مين تصدقون؟"}, {"i": 68, "a": 134.21, "b": 135.916, "text": "رسالة سالم اللي بجوالي؟"}, {"i": 69, "a": 136.246, "b": 137.868, "text": "ولا الولد اللي بالدرج؟"}];
